module DfeRb
  # The IBGE table of municipalities every DF-e's city codes follow (data/municipalities.tsv,
  # regenerated by script/update_tables). Loaded on first use.
  module Cities
    DATA = File.expand_path("data/municipalities.tsv", __dir__)

    module_function

    # "Campo Grande" for "5002704", or nil.
    def name(code) = names[code.to_s]

    # The IBGE code of the city called `name` in `state`, ignoring case and accents, or nil.
    def code(name, state)
      codes[[States.code(state), fold(name)]]
    rescue ArgumentError
      nil
    end

    def fold(text)
      text.to_s.unicode_normalize(:nfkd).gsub(/\p{Mn}/, "").downcase.gsub(/[^a-z0-9]+/, " ").strip
    end

    def names
      @names ||= File.readlines(DATA, chomp: true, encoding: "UTF-8").to_h { |line| line.split("\t", -1) }.freeze
    end

    def codes
      @codes ||= names.to_h { |code, name| [[code[0, 2], fold(name)], code] }.freeze
    end
  end
end
